import type { BankQuestion } from "@/lib/bank";

/** Properties of Matter (Physics (JEE/NEET)): 118 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-fluids-elasticity-1","question":"The SI unit of Young's modulus is:","options":["N","N m","N/m²","N/m"],"answer":2,"explanation":"Young's modulus = stress/strain; strain has no unit, so Y has the unit of stress, N/m² (pascal).","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-2","question":"Bernoulli's theorem for the flow of an ideal fluid is a statement of the conservation of:","options":["energy","linear momentum","mass","angular momentum"],"answer":0,"explanation":"P + ½ρv² + ρgh = constant is the work–energy principle per unit volume. Conservation of mass gives the equation of continuity, Av = constant.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-3","question":"Taking g = 10 m/s² and the density of water as 1000 kg/m³, the pressure at a depth of 10 m in water in excess of atmospheric pressure is:","options":["1 × 10⁵ Pa","1 × 10⁴ Pa","2 × 10⁵ Pa","1 × 10³ Pa"],"answer":0,"explanation":"Gauge pressure = ρgh = 1000 × 10 × 10 = 10⁵ Pa. The absolute pressure would be about 2 × 10⁵ Pa.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-4","question":"A wire of length 2 m and cross-section 1 mm² is stretched by a force of 100 N. If Young's modulus is 2 × 10¹¹ N/m², the extension is:","options":["0.1 mm","10 mm","0.5 mm","1 mm"],"answer":3,"explanation":"ΔL = FL/AY = 100 × 2/(10⁻⁶ × 2 × 10¹¹) = 200/(2 × 10⁵) = 10⁻³ m = 1 mm.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-5","question":"In a hydraulic lift the pistons have areas of 10 cm² and 1000 cm². A force of 100 N on the small piston can support a load of:","options":["10 N","10³ N","10⁴ N","10⁵ N"],"answer":2,"explanation":"By Pascal's law the pressure is the same: F₂ = F₁ × A₂/A₁ = 100 × 100 = 10⁴ N.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-6","question":"Water flows steadily through a horizontal pipe. Where the radius of the pipe is halved, the speed of the water becomes:","options":["1/2 times","1/4 times","4 times","2 times"],"answer":2,"explanation":"Continuity: A₁v₁ = A₂v₂ and A ∝ r², so halving r reduces the area to 1/4 and the speed rises 4 times.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-7","question":"The excess pressure inside a soap bubble of radius 1 cm, if the surface tension of the soap solution is 0.03 N/m, is:","options":["3 Pa","24 Pa","12 Pa","6 Pa"],"answer":2,"explanation":"A soap bubble has two surfaces, so ΔP = 4T/r = 4 × 0.03/0.01 = 12 Pa. 2T/r (6 Pa) is for a liquid drop or an air bubble inside a liquid.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-8","question":"An iceberg (density 900 kg/m³) floats in sea water (density 1030 kg/m³). The fraction of its volume above the water surface is about:","options":["90%","12.6%","87.4%","10%"],"answer":1,"explanation":"Fraction submerged = 900/1030 ≈ 0.874, so about 12.6% lies above. 10% above is the answer for fresh water (density 1000).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-9","question":"Water rises to a height h in a capillary tube of radius r. In another tube of the same glass but of radius 2r, dipped in the same water, it rises to:","options":["h/4","h/2","h","2h"],"answer":1,"explanation":"By Jurin's law h = 2T cosθ/(rρg), so h ∝ 1/r: doubling the radius halves the rise.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-10","question":"A tank on the ground contains water to a height of 10 m. A small hole is made in its side 2 m below the water surface. The water stream strikes the ground at a horizontal distance from the tank of (g = 10 m/s²):","options":["8 m","10 m","6.3 m","4 m"],"answer":0,"explanation":"Efflux speed v = √(2g × 2) = √40 m/s. The hole is 8 m above the ground, so the fall time is √(2 × 8/10) = √1.6 s. Range = √40 × √1.6 = √64 = 8 m.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-11","question":"Water (surface tension 0.07 N/m, angle of contact 0°) rises in a clean glass capillary of radius 0.1 mm. Taking g = 10 m/s², the height of the rise is:","options":["7 cm","1.4 cm","28 cm","14 cm"],"answer":3,"explanation":"h = 2T cosθ/(rρg) = 2 × 0.07/(10⁻⁴ × 1000 × 10) = 0.14/1 m = 14 cm. Forgetting the factor 2 gives 7 cm.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-12","question":"A wire stretched by a force of 200 N extends by 1 mm (within the elastic limit). The elastic potential energy stored in it is:","options":["1 J","0.05 J","0.1 J","0.2 J"],"answer":2,"explanation":"The force grows from 0 to 200 N during the stretch, so U = ½Fx = ½ × 200 × 10⁻³ = 0.1 J. Fx = 0.2 J would assume the full force acted throughout.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-13","question":"The bulk modulus of water is 2.2 × 10⁹ Pa. When the pressure on it is increased by 1.1 × 10⁷ Pa, its volume decreases by:","options":["0.05%","0.5%","2%","5%"],"answer":1,"explanation":"ΔV/V = ΔP/B = 1.1 × 10⁷/2.2 × 10⁹ = 5 × 10⁻³ = 0.5%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-14","question":"Two wires of the same material have lengths L and 2L and radii 2r and r respectively. They are stretched by equal forces. The ratio of their extensions is:","options":["1 : 8","8 : 1","1 : 2","1 : 4"],"answer":0,"explanation":"ΔL = FL/(πr²Y) ∝ L/r². First: L/4r²; second: 2L/r². Ratio = (1/4)/2 = 1/8.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-15","question":"A metal ball of radius 1 mm and density 10,000 kg/m³ falls through a liquid of density 1000 kg/m³ and viscosity 1 Pa s. Its terminal speed is (g = 10 m/s²):","options":["4 cm/s","2 cm/s","1 cm/s","0.2 cm/s"],"answer":1,"explanation":"v = 2r²(ρ − σ)g/9η = 2 × 10⁻⁶ × 9000 × 10/9 = 0.02 m/s = 2 cm/s. Ignoring the buoyancy (using ρ alone) would give about 2.2 cm/s.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-16","question":"Eight identical rain droplets, each falling with terminal speed v, coalesce to form a single drop. The terminal speed of the big drop is:","options":["8v","2v","16v","4v"],"answer":3,"explanation":"Volume is conserved: 8 × (4/3)πr³ = (4/3)πR³, so R = 2r. Terminal speed ∝ r², so it becomes 4v.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-17","question":"Water flows through a horizontal pipe whose cross-section narrows from 4 cm² to 2 cm². The speed in the wider part is 2 m/s. The pressure difference between the wide and narrow parts is:","options":["12000 Pa","8000 Pa","6000 Pa","2000 Pa"],"answer":2,"explanation":"Continuity gives 4 m/s in the narrow part. Bernoulli: ΔP = ½ρ(v₂² − v₁²) = ½ × 1000 × (16 − 4) = 6000 Pa, higher in the wider part.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-18","question":"When a wire is stretched, its length increases by 1% and its diameter decreases by 0.25%. Its volume:","options":["increases by 0.5%","remains unchanged","decreases by 0.5%","increases by 1.5%"],"answer":0,"explanation":"V = (π/4)d²L, so ΔV/V = ΔL/L + 2Δd/d = 1% − 0.5% = +0.5%. The volume would stay constant only for Poisson's ratio 0.5 (here it is 0.25).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-19","question":"The surface tension of a soap solution is 0.03 N/m. The work done in blowing a soap bubble from a radius of 1 cm to a radius of 2 cm is:","options":["14.4π × 10⁻⁵ J","2.4π × 10⁻⁵ J","7.2π × 10⁻⁵ J","3.6π × 10⁻⁵ J"],"answer":2,"explanation":"A bubble has two surfaces: ΔA = 2 × 4π(r₂² − r₁²) = 8π × 3 × 10⁻⁴ = 24π × 10⁻⁴ m². W = TΔA = 0.03 × 24π × 10⁻⁴ = 7.2π × 10⁻⁵ J. Counting one surface gives half this.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-20","question":"A liquid drop of radius R breaks up into 1000 identical droplets. If the surface tension is T, the energy required is:","options":["36πR²T","40πR²T","9πR²T","4πR²T"],"answer":0,"explanation":"Each droplet has radius R/10. New area = 1000 × 4π(R/10)² = 40πR²; initial area = 4πR². Energy = T × (40πR² − 4πR²) = 36πR²T.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-21","question":"A steel rod is clamped rigidly at both ends at room temperature and then heated through 50 °C. If Y = 2 × 10¹¹ N/m² and α = 1.2 × 10⁻⁵ per °C, the thermal stress developed is:","options":["1.2 × 10⁸ N/m²","2.4 × 10⁸ N/m²","6 × 10⁷ N/m²","1.2 × 10⁶ N/m²"],"answer":0,"explanation":"The rod is prevented from expanding, so the strain is αΔT. Stress = YαΔT = 2 × 10¹¹ × 1.2 × 10⁻⁵ × 50 = 1.2 × 10⁸ N/m², independent of length and cross-section.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-22","question":"A block of density 900 kg/m³ floats completely submerged at the interface between a layer of oil (density 800 kg/m³) and water (density 1000 kg/m³) below it. The fraction of the block's volume in the water is:","options":["1/4","1/3","1/2","2/3"],"answer":2,"explanation":"Weight = buoyancy: 900V = 1000xV + 800(1 − x)V → 200x = 100 → x = 1/2.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-fluids-elasticity-23","question":"How many of the following statements are correct?\n(A) The viscosity of a liquid decreases as its temperature rises.\n(B) The viscosity of a gas increases as its temperature rises.\n(C) The surface tension of a liquid increases as its temperature rises.\n(D) Detergents lower the surface tension of water.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B and D are correct. C is wrong: surface tension decreases with temperature and becomes zero at the critical temperature. So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-24","question":"Assertion (A): Steel is more elastic than rubber.\nReason (R): For the same stress, the strain produced in steel is much smaller than in rubber, so steel has a larger Young's modulus.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In physics 'more elastic' means a larger modulus, i.e. greater opposition to deformation. Steel's Y (about 2 × 10¹¹ Pa) is far larger than rubber's, precisely because it strains less for the same stress, so R explains A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-fluids-elasticity-25","question":"A cylindrical vessel of radius 10 cm containing water is rotated about its vertical axis at 10 rad/s. In the steady state, the water at the wall stands higher than at the axis by (g = 10 m/s²):","options":["0.5 cm","10 cm","5 cm","2.5 cm"],"answer":2,"explanation":"The free surface is a paraboloid with height difference ω²R²/2g = 100 × 0.01/20 = 0.05 m = 5 cm.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-26","question":"An open rectangular tank 2 m long, partly filled with water, accelerates horizontally along its length at 5 m/s². In the steady state the difference between the water levels at its front and rear walls is (g = 10 m/s²):","options":["2 m","0.5 m","1 m","0.25 m"],"answer":2,"explanation":"The free surface tilts so that tanθ = a/g = 1/2. Over the 2 m length the level difference is 2 × 1/2 = 1 m, higher at the rear.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-27","question":"A uniform steel rod 10 m long (density 8000 kg/m³, Y = 2 × 10¹¹ N/m²) hangs vertically from one end. The elongation of the rod due to its own weight is (g = 10 m/s²):","options":["2 × 10⁻⁵ m","8 × 10⁻⁵ m","1 × 10⁻⁵ m","4 × 10⁻⁵ m"],"answer":0,"explanation":"The tension rises linearly from zero at the bottom, so δ = ρgL²/2Y = 8000 × 10 × 100/(4 × 10¹¹) = 2 × 10⁻⁵ m. Using the full weight at every section would give double.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-28","question":"Water rises to a height of 6 cm in a capillary tube. If the tube is pushed down so that only 4 cm of it remains above the water surface, then:","options":["water does not rise at all","water rises to the top and the radius of curvature of the meniscus becomes 1.5 times","water rises only to 4 cm and the radius of the meniscus becomes 2/3 times","water overflows from the top like a fountain"],"answer":1,"explanation":"hR = 2T/ρg is constant (R = radius of curvature of the meniscus). With h limited to 4 cm, R becomes 6/4 = 1.5 times its value; the meniscus flattens and the water never overflows, which would violate energy conservation.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-29","question":"A liquid flows steadily under a fixed pressure difference through a narrow tube of radius r and length L at a volume rate Q. If a second tube of radius r/2 and length L/2 is joined in series with the first, keeping the same total pressure difference, the flow rate becomes:","options":["Q/3","Q/17","Q/9","Q/8"],"answer":2,"explanation":"Poiseuille's law gives a flow resistance ∝ L/r⁴. The second tube has (L/2)/(r/2)⁴ = 8L/r⁴, i.e. 8 times the first, so total resistance = 9 times and the flow falls to Q/9.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-30","question":"Match the quantity (List I) with its expression (List II). List I: (P) viscous drag on a small sphere; (Q) excess pressure inside a liquid drop; (R) excess pressure inside a soap bubble; (S) speed of efflux from a hole at depth h. List II: (1) √(2gh); (2) 4T/r; (3) 6πηrv; (4) 2T/r.","options":["P-3, Q-4, R-2, S-1","P-3, Q-2, R-4, S-1","P-3, Q-4, R-1, S-2","P-1, Q-4, R-2, S-3"],"answer":0,"explanation":"Stokes' law gives 6πηrv. A drop has one surface (2T/r), a soap bubble two (4T/r). Torricelli's law gives √(2gh), the speed of free fall through h.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-fluids-elasticity-31", "question": "Hydraulic brakes in automobiles work on the principle of:", "options": ["Bernoulli's theorem", "Archimedes' principle", "Pascal's law", "Stokes' law"], "answer": 2, "explanation": "Pascal's law: pressure applied to an enclosed liquid is transmitted undiminished to every part of it, so a small force on the master cylinder produces a large force at the wheel cylinders.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-32", "question": "The angle of contact between mercury and clean glass is:", "options": ["obtuse (about 140°)", "zero", "acute (about 8°)", "exactly 90°"], "answer": 0, "explanation": "Mercury does not wet glass, so its angle of contact is obtuse (about 135°–140°); that is why mercury is depressed in a glass capillary.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-33", "question": "Poisson's ratio is the ratio of:", "options": ["longitudinal stress to longitudinal strain", "lateral strain to longitudinal strain", "volumetric strain to longitudinal strain", "shear stress to shear strain"], "answer": 1, "explanation": "Poisson's ratio σ = lateral strain/longitudinal strain (in magnitude); it has no unit. Stress/strain ratios are elastic moduli.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-34", "question": "A body weighs 50 N in air and 40 N when fully immersed in water. The relative density of the material of the body is:", "options": ["1.25", "4", "5", "0.8"], "answer": 2, "explanation": "Loss of weight = upthrust = weight of water displaced = 10 N. Relative density = weight in air/loss of weight = 50/10 = 5.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-35", "question": "A tangential force of 10⁴ N acts on the upper face (area 0.01 m²) of a cube of side 10 cm whose lower face is fixed, and the upper face shifts by 0.02 mm. The modulus of rigidity of the material is:", "options": ["5 × 10⁹ N/m²", "5 × 10¹⁰ N/m²", "2 × 10⁹ N/m²", "5 × 10⁸ N/m²"], "answer": 0, "explanation": "Shear stress = 10⁴/0.01 = 10⁶ Pa; shear strain = 0.02 mm/100 mm = 2 × 10⁻⁴. Rigidity modulus = 10⁶/(2 × 10⁻⁴) = 5 × 10⁹ N/m².", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-36", "question": "A vessel holds a 20 cm layer of water (density 1000 kg/m³) with a 10 cm layer of oil (density 800 kg/m³) floating on it. The gauge pressure at the bottom of the vessel is (g = 10 m/s²):", "options": ["2000 Pa", "2800 Pa", "3000 Pa", "2600 Pa"], "answer": 1, "explanation": "Each layer adds ρgh: 800 × 10 × 0.1 + 1000 × 10 × 0.2 = 800 + 2000 = 2800 Pa above atmospheric pressure.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-37", "question": "A flat plate of area 0.1 m² is moved at a constant speed of 0.1 m/s over a layer of oil 1 mm thick lying on a fixed surface. If the viscosity of the oil is 0.5 Pa s, the force needed is:", "options": ["0.5 N", "50 N", "5 N", "0.05 N"], "answer": 2, "explanation": "F = ηA(dv/dy) = 0.5 × 0.1 × (0.1/0.001) = 0.5 × 0.1 × 100 = 5 N.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-38", "question": "A wire can just support a maximum load W before breaking. Another wire of the same material, twice as long and of twice the radius, can support a maximum load of:", "options": ["2W", "W", "8W", "4W"], "answer": 3, "explanation": "Breaking load = breaking stress × area; breaking stress is a property of the material and length does not matter. Doubling the radius makes the area 4 times, so the load is 4W.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-39", "question": "A glass capillary tube, shorter than the height to which water would normally rise in it, is dipped in water inside an orbiting satellite (weightless conditions). The water:", "options": ["does not rise at all", "rises to the top of the tube but does not overflow", "rises to the normal height and spills over", "is depressed below the outer level"], "answer": 1, "explanation": "With g_eff = 0, the rise h = 2T cos θ/(rρg) is formally infinite, so water climbs to the top of the tube. It does not overflow: at the top the meniscus adjusts its radius of curvature, and surface tension cannot push liquid out of the tube.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-40", "question": "In a horizontal venturimeter the cross-sections at the inlet and the throat are 10 cm² and 5 cm². A water manometer connected between them shows a level difference of 15 cm. The volume flow rate of water is (g = 10 m/s²):", "options": ["0.5 litre/s", "1 litre/s", "2 litres/s", "1.5 litres/s"], "answer": 1, "explanation": "Continuity: v₂ = 2v₁. Bernoulli: P₁ − P₂ = ½ρ(4v₁² − v₁²) = ρgh, so v₁² = 2gh/3 = 2 × 10 × 0.15/3 = 1, giving v₁ = 1 m/s. Flow rate = 10 × 10⁻⁴ m² × 1 m/s = 10⁻³ m³/s = 1 litre/s.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-41", "question": "An air bubble of radius 0.1 mm is 10 cm below the surface of water (surface tension 0.07 N/m, g = 10 m/s²). The pressure inside the bubble exceeds the atmospheric pressure by:", "options": ["1400 Pa", "2400 Pa", "3800 Pa", "1000 Pa"], "answer": 1, "explanation": "Pressure in the water at that depth = P₀ + ρgh = P₀ + 1000 Pa, and a bubble inside a liquid has one surface, adding 2T/r = 2 × 0.07/10⁻⁴ = 1400 Pa. Total excess = 2400 Pa; using 4T/r (soap bubble) would be wrong here.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-42", "question": "A steel wire (Y = 2 × 10¹¹ N/m²) is under a tensile stress of 2 × 10⁸ N/m² within the elastic limit. The elastic potential energy stored per unit volume is:", "options": ["10⁵ J/m³", "2 × 10⁵ J/m³", "10⁸ J/m³", "5 × 10⁴ J/m³"], "answer": 0, "explanation": "Energy density = ½ × stress × strain = stress²/(2Y) = (2 × 10⁸)²/(2 × 2 × 10¹¹) = 4 × 10¹⁶/(4 × 10¹¹) = 10⁵ J/m³.", "difficulty": "hard", "source": "NEET · JEE Main"},
  {"id": "phy-fluids-elasticity-43", "question": "Water (viscosity 10⁻³ Pa s) flows at 0.1 m/s through a pipe of diameter 2 cm. The Reynolds number of the flow is:", "options": ["200", "20,000", "2000", "1000"], "answer": 2, "explanation": "Re = ρvD/η = 1000 × 0.1 × 0.02/10⁻³ = 2000, which is around the limit below which flow in a pipe is usually laminar.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-44", "question": "A wooden block floats in water with 3/5 of its volume submerged. In a certain oil it floats with 4/5 of its volume submerged. The density of the oil is:", "options": ["600 kg/m³", "800 kg/m³", "750 kg/m³", "667 kg/m³"], "answer": 2, "explanation": "Block density = (3/5) × 1000 = 600 kg/m³. In oil, 600 = ρ_oil × 4/5, so ρ_oil = 750 kg/m³.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-45", "question": "A small ball of density ρ/2 is held at the bottom of a container of liquid of density ρ, kept in a lift that is accelerating upward at g/2. When released, the acceleration of the ball relative to the container (neglecting viscosity) is (g = 10 m/s²):", "options": ["5 m/s²", "10 m/s²", "20 m/s²", "15 m/s²"], "answer": 3, "explanation": "In the lift frame g_eff = g + g/2 = 15 m/s². Net upward force = (ρ − ρ/2)Vg_eff, on mass (ρ/2)V, so the relative acceleration is g_eff = 15 m/s².", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-46", "question": "A tank of cross-section 1 m² is filled with water to a height of 5 m. A hole of area 10 cm² is opened at its bottom. The time taken for the tank to empty completely is (g = 10 m/s²):", "options": ["500 s", "1000 s", "2000 s", "100 s"], "answer": 1, "explanation": "A dh/dt = −a√(2gh) gives t = (A/a)√(2H/g) = (1/10⁻³) × √(2 × 5/10) = 1000 × 1 = 1000 s. The rate is not constant, so dividing volume by the initial flow rate gives only half (500 s).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-47", "question": "A thin film of water 0.01 mm thick lies between two flat glass plates of area 0.01 m² each (surface tension 0.07 N/m, angle of contact zero). The force needed to pull the plates apart normally is about:", "options": ["70 N", "14 N", "140 N", "280 N"], "answer": 2, "explanation": "The meniscus at the edge has radius of curvature d/2, so the pressure in the film is lower by T/(d/2) = 2T/d. F = 2TA/d = 2 × 0.07 × 0.01/10⁻⁵ = 140 N.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-48", "question": "The bulk modulus of water is 2 × 10⁹ N/m². The depth in a lake at which the density of water is 0.1% greater than at the surface is about (g = 10 m/s²):", "options": ["20 m", "200 m", "2 km", "2 m"], "answer": 1, "explanation": "A 0.1% rise in density means ΔV/V = 10⁻³, needing P = BΔV/V = 2 × 10⁶ Pa. Depth = P/(ρg) = 2 × 10⁶/10⁴ = 200 m.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-49", "question": "1000 identical water droplets, each of radius 10⁻⁶ m, coalesce into a single drop. If all the surface energy released heats the water, its temperature rises by about (surface tension 0.07 N/m, specific heat 4200 J/kg K):", "options": ["0.45 °C", "0.045 °C", "0.0045 °C", "4.5 °C"], "answer": 1, "explanation": "Energy released per unit mass = 3T(1/r − 1/R)/ρ with R = 10r = 10⁻⁵ m: 3 × 0.07 × (10⁶ − 10⁵)/1000 = 189 J/kg. ΔT = 189/4200 ≈ 0.045 °C.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-50", "question": "How many of the following statements about fluid flow are correct?\n(A) Bernoulli's theorem holds for the flow of a viscous liquid.\n(B) In streamline flow, the velocity of the fluid at a given point does not change with time.\n(C) Two streamlines can never cross each other.\n(D) The equation of continuity follows from the conservation of mass.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "B, C and D are correct (crossing streamlines would mean two velocities at one point). A is wrong: Bernoulli's theorem assumes a non-viscous, incompressible, steady flow, since viscosity dissipates energy.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-51", "question": "Assertion (A): A ship floats with more of its hull above the water in sea water than in river water.\nReason (R): Sea water is denser than river water, so a smaller submerged volume displaces a weight of water equal to the ship's weight.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "A floating ship displaces its own weight of liquid; denser sea water needs a smaller volume for the same weight, so the ship rides higher. R gives exactly this reason.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-52", "question": "Match the principle (List I) with an application (List II). List I: (P) Bernoulli's theorem; (Q) Pascal's law; (R) Stokes' law; (S) Archimedes' principle. List II: (1) hydraulic brakes; (2) dynamic lift on an aeroplane wing; (3) hydrometer; (4) Millikan's oil-drop experiment.", "options": ["P-2, Q-1, R-4, S-3", "P-1, Q-2, R-4, S-3", "P-2, Q-1, R-3, S-4", "P-4, Q-1, R-2, S-3"], "answer": 0, "explanation": "Wing lift comes from faster flow (lower pressure) above the wing: Bernoulli. Hydraulic brakes use Pascal's law. Millikan used the viscous drag (Stokes) on oil drops at terminal speed. A hydrometer floats by Archimedes' principle.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-53", "question": "A solid block hung from a spring balance reads 60 N in air, 40 N when fully immersed in water and 44 N when fully immersed in a liquid X. The relative densities of the block and of liquid X are respectively:", "options": ["1.5 and 0.8", "3 and 1.25", "3 and 0.8", "2.5 and 0.8"], "answer": 2, "explanation": "Upthrust in water = 20 N, so the block's relative density = 60/20 = 3. Upthrust in X = 16 N, so the relative density of X = 16/20 = 0.8.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-fluids-elasticity-54", "question": "A hollow sphere has an inner radius equal to half its outer radius. It just floats fully submerged in water. The relative density of its material is:", "options": ["8/7", "7/8", "2", "4/3"], "answer": 0, "explanation": "Weight = upthrust: ρ(4/3)π(R³ − R³/8) = ρ_w(4/3)πR³, so ρ × 7/8 = ρ_w and the relative density is 8/7 ≈ 1.14.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-55", "question": "A block hangs from a steel wire fixed to the ceiling of a lift. When the lift is at rest the extension of the wire is 1 mm. When the lift accelerates upward at 2 m/s² (g = 10 m/s²), the extension and the elastic energy stored become respectively:", "options": ["1.2 mm and 1.2 times", "1.2 mm and 1.44 times", "0.8 mm and 0.64 times", "1.44 mm and 1.2 times"], "answer": 1, "explanation": "Tension = m(g + a) = 1.2 mg, so the extension is 1.2 mm. Energy = ½kx² ∝ x², so it becomes 1.2² = 1.44 times.", "difficulty": "very-hard", "source": "NEET · JEE Main"},
  {"id": "phy-fluids-elasticity-56", "question": "A uniform metal rod 1 m long (density 8000 kg/m³) rotates in a horizontal plane about a vertical axis through one end at 100 rad/s. The tensile stress in the rod at the axis is:", "options": ["8 × 10⁷ N/m²", "2 × 10⁷ N/m²", "4 × 10⁷ N/m²", "4 × 10⁶ N/m²"], "answer": 2, "explanation": "Tension at distance x from the axis = ½ρAω²(L² − x²), largest at the axis: stress = ½ρω²L² = ½ × 8000 × 10⁴ × 1 = 4 × 10⁷ N/m². 8 × 10⁷ treats all the mass as moving at radius L.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-fluids-elasticity-57", "question": "A closed tank contains water with air above it at a gauge pressure of 5 × 10⁴ Pa. A small hole is made in the side of the tank 5 m below the water surface. The speed of efflux is about (g = 10 m/s²):", "options": ["10 m/s", "14.1 m/s", "17.3 m/s", "20 m/s"], "answer": 1, "explanation": "Bernoulli: ½v² = P_gauge/ρ + gh = 50 + 50 = 100 J/kg, so v = √200 ≈ 14.1 m/s. Torricelli's √(2gh) = 10 m/s ignores the extra air pressure.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-58", "question": "Water is siphoned out of a large open tank through a uniform tube. The outlet is 5 m below the water surface in the tank and the highest point of the tube is 1 m above that surface. Taking atmospheric pressure as 1 × 10⁵ Pa and g = 10 m/s², the pressure at the highest point of the tube is:", "options": ["9 × 10⁴ Pa", "5 × 10⁴ Pa", "6 × 10⁴ Pa", "4 × 10⁴ Pa"], "answer": 3, "explanation": "Outlet speed v = √(2gh) = √100 = 10 m/s, the same everywhere in the uniform tube. At the top: P = P₀ − ρg(1) − ½ρv² = 10⁵ − 10⁴ − 5 × 10⁴ = 4 × 10⁴ Pa.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-59", "question": "A glass capillary of radius 0.5 mm is dipped in mercury (surface tension 0.49 N/m, angle of contact 135°, density 13,600 kg/m³). Taking g = 10 m/s², the mercury level in the tube is:", "options": ["raised by about 1.0 cm", "depressed by about 1.4 cm", "depressed by about 1.0 cm", "depressed by about 0.5 cm"], "answer": 2, "explanation": "h = 2T cos θ/(rρg) = 2 × 0.49 × (−0.707)/(5 × 10⁻⁴ × 13600 × 10) = −0.693/68 ≈ −0.0102 m. The negative sign means a depression of about 1.0 cm; dropping cos θ gives 1.4 cm.", "difficulty": "very-hard", "source": "NEET · JEE Main"},
  {"id": "phy-fluids-elasticity-60", "question": "Two rods of the same length and cross-section, one of steel (Y = 2 × 10¹¹ N/m²) and one of brass (Y = 1 × 10¹¹ N/m²), are joined end to end and stretched by a force. The effective Young's modulus of the composite rod is:", "options": ["1.5 × 10¹¹ N/m²", "3 × 10¹¹ N/m²", "1.33 × 10¹¹ N/m²", "0.67 × 10¹¹ N/m²"], "answer": 2, "explanation": "Same force in both; extensions add: F(2L)/(AY) = FL/(AY₁) + FL/(AY₂), so Y = 2Y₁Y₂/(Y₁ + Y₂) = 2 × 2 × 1/3 × 10¹¹ ≈ 1.33 × 10¹¹ N/m². The plain average 1.5 × 10¹¹ applies to neither arrangement.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-fluids-elasticity-61","question":"A wooden cube of side 10 cm floats in water with 2/3 of its volume submerged (density of water 1000 kg/m³). The least mass that must be placed on top of it to submerge it completely is about:","options":["333 g","1000 g","667 g","500 g"],"answer":0,"explanation":"Fully submerging it needs extra buoyancy equal to the weight of water in the remaining 1/3 of the volume: (1/3) × 1000 cm³ × 1 g/cm³ ≈ 333 g. 667 g is the mass of the cube itself.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-62","question":"Water flows through a horizontal pipe. Between two sections its speed rises from 2 m/s to 4 m/s. The pressure difference between the two sections is (density 1000 kg/m³):","options":["2000 Pa","6000 Pa","12000 Pa","3000 Pa"],"answer":1,"explanation":"Bernoulli: ΔP = ½ρ(v₂² − v₁²) = 0.5 × 1000 × (16 − 4) = 6000 Pa, the pressure being lower where the speed is higher. ½ρ(v₂ − v₁)² = 2000 Pa is the common slip.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-63","question":"A thin wire ring of radius 2 cm lies flat on a water surface (surface tension 0.07 N/m). Apart from its weight, the extra force needed to just pull it free of the surface is about:","options":["8.8 × 10⁻³ N","3.5 × 10⁻² N","1.76 × 10⁻² N","4.4 × 10⁻³ N"],"answer":2,"explanation":"The water film clings to both the inner and the outer edge of the ring, so the length of contact is 2 × 2πr. F = 4πrT = 4π × 0.02 × 0.07 ≈ 1.76 × 10⁻² N. Counting only one circumference gives 8.8 × 10⁻³ N.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-64","question":"A dam 10 m wide holds water to a depth of 5 m (density 1000 kg/m³, g = 10 m/s²). The torque of the water's thrust about the bottom edge of the dam is about:","options":["3.1 × 10⁶ N m","6.25 × 10⁶ N m","1.25 × 10⁶ N m","2.1 × 10⁶ N m"],"answer":3,"explanation":"Total thrust F = ρgwh²/2 = 1.25 × 10⁶ N, acting at h/3 above the base because the pressure grows with depth. Torque = ρgwh³/6 = 1000 × 10 × 10 × 125/6 ≈ 2.1 × 10⁶ N m. Placing the thrust at mid-depth gives 3.1 × 10⁶ N m.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-65","question":"A solid sphere (bulk modulus 10¹¹ Pa) is lowered into the sea to a depth where the pressure is greater by 10⁷ Pa. The fractional decrease in its radius is about:","options":["3.3 × 10⁻⁵","1.0 × 10⁻⁴","3.0 × 10⁻⁴","1.0 × 10⁻⁵"],"answer":0,"explanation":"ΔV/V = ΔP/B = 10⁷/10¹¹ = 10⁻⁴. Since V ∝ r³, Δr/r = (1/3)ΔV/V ≈ 3.3 × 10⁻⁵. 10⁻⁴ is the volume strain, not the change in radius.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-fluids-elasticity-66", "question": "An open tank of water is in a lift that accelerates upward at 5 m/s². Water spurts from a small hole 1.2 m below the water surface (g = 10 m/s²). The speed of efflux relative to the tank is:", "options": ["4.9 m/s", "3.5 m/s", "7.3 m/s", "6 m/s"], "answer": 3, "explanation": "In the lift's frame the effective gravity is g + a = 15 m/s², so v = √(2(g + a)h) = √(2 × 15 × 1.2) = 6 m/s. √(2gh) ≈ 4.9 m/s ignores the acceleration.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"phy-fluids-elasticity-67","question":"Water leaves a tap with a cross-section of 1.0 cm² at 1.0 m/s and falls vertically as a smooth stream (g = 10 m/s²). Its cross-sectional area 15 cm below the tap is:","options":["0.25 cm²","0.5 cm²","0.75 cm²","1.0 cm²"],"answer":1,"explanation":"v² = 1² + 2 × 10 × 0.15 = 4, so v = 2 m/s. By continuity, A = 1.0 × 1/2 = 0.5 cm². 0.25 cm² comes from taking A ∝ 1/v² instead of 1/v.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-fluids-elasticity-68", "question": "A steel wire is made of two parts, each 1 m long, with cross-sections 1 mm² and 2 mm², joined end to end. It hangs vertically and carries a load of 100 N (Y = 2 × 10¹¹ N/m², weight of the wire neglected). Its total extension is:", "options": ["0.50 mm", "1.00 mm", "0.75 mm", "0.33 mm"], "answer": 2, "explanation": "Both parts carry the same 100 N. Δl = (F/Y)(l₁/A₁ + l₂/A₂) = (100/(2 × 10¹¹))(10⁶ + 0.5 × 10⁶) = 7.5 × 10⁻⁴ m = 0.75 mm. 1.00 mm treats the whole 2 m wire as 1 mm² thick.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-69", "question": "A wire hangs vertically from a support and is stretched only by its own weight. Its breaking stress is 8 × 10⁸ N/m² and its density 8000 kg/m³ (g = 10 m/s²). The greatest length it can have without breaking is:", "options": ["20 km", "5 km", "1 km", "10 km"], "answer": 3, "explanation": "The stress is greatest at the top, where it equals the weight of the whole wire per unit area: ρgL. Setting ρgL = 8 × 10⁸ gives L = 8 × 10⁸/(8000 × 10) = 10 km, independent of the cross-section. 20 km uses the average stress ρgL/2.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"phy-fluids-elasticity-70","question":"Two layers of liquid, each of thickness d, lie between two large parallel plates. The upper layer has viscosity η and the lower 2η. The lower plate is fixed and the upper plate moves at a steady speed v. The viscous force per unit area on the upper plate is:","options":["2ηv/(3d)","3ηv/(2d)","ηv/(2d)","ηv/d"],"answer":0,"explanation":"The shear stress is the same in both layers. With interface speed u: η(v − u)/d = 2η(u − 0)/d, so u = v/3. Stress = η(v − v/3)/d = 2ηv/(3d). Treating the whole gap 2d as a single layer of viscosity η gives ηv/(2d).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-71","question":"A U-tube has two vertical limbs joined by a horizontal section 30 cm long and contains water. It is rotated at 10 rad/s about the vertical axis of one of its limbs (g = 10 m/s²). The difference between the water levels in the two limbs is:","options":["45 cm, higher in the limb on the axis","45 cm, higher in the outer limb","90 cm, higher in the outer limb","15 cm, higher in the outer limb"],"answer":1,"explanation":"Along the horizontal section, dP/dr = ρω²r, so P(L) − P(0) = ρω²L²/2. This must be balanced by the difference in water columns: ρgΔh = ρω²L²/2, giving Δh = 100 × 0.09/20 = 0.45 m, with the outer limb higher. 90 cm forgets the ½ from integrating.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-72","question":"An ice cube containing a small stone floats in a glass of water. When the ice melts completely, the water level in the glass:","options":["Stays the same","Rises","Falls","First rises, then returns to the original level"],"answer":2,"explanation":"While floating, the stone displaces water equal to its weight, which is more than its own volume because it is denser than water. After melting the stone sinks and displaces only its own volume, while the melted ice exactly fills the volume it displaced. So the level falls. Pure ice alone would leave the level unchanged.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-73","question":"A large open tank, 2 m tall and full of water, stands on a platform 3 m high. A small hole may be made anywhere in its vertical side (g = 10 m/s²). To make the jet land as far as possible from the foot of the platform, the hole should be made:","options":["At the bottom of the tank, giving a range of 4 m","1 m below the water surface, giving a range of 4 m","2.5 m below the water surface, giving a range of 5 m","At the bottom of the tank, giving a range of 2√6 m ≈ 4.9 m"],"answer":3,"explanation":"For a hole at depth x, efflux speed √(2gx) from height (5 − x) gives range R = 2√(x(5 − x)), which keeps increasing until x = 2.5 m. But the tank is only 2 m deep, so the best possible hole is at the bottom: R = 2√(2 × 3) = 2√6 ≈ 4.9 m. 2.5 m is not available (hidden condition), and the mid-height rule applies only when the tank stands on the ground.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-74","question":"A liquid flows through a horizontal tube of radius r and length L at a rate Q under a pressure difference P. A second tube of radius r/2 and length L/2 is connected in series with it, and the same pressure difference P is applied across the combination. The new flow rate is:","options":["Q/9","Q/17","Q/3","Q/5"],"answer":0,"explanation":"By Poiseuille's law the flow resistance is proportional to L/r⁴. The second tube has (L/2)/(r⁴/16) = 8 times the resistance of the first, so the total is 9 times and the flow falls to Q/9. Q/17 forgets to halve the length.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-fluids-elasticity-75", "question": "Two soap bubbles of radii 3 cm and 4 cm coalesce in a vacuum to form a single bubble, the temperature staying constant. The radius of the new bubble is:", "options": ["7 cm", "5 cm", "4.5 cm", "3.5 cm"], "answer": 1, "explanation": "In a vacuum the gas pressure inside equals 4T/r, so PV ∝ (4T/r)(r³) ∝ r². Since the gas is conserved at constant temperature, PV is conserved: r² = 3² + 4² gives r = 5 cm. Conserving volume would give (27 + 64)^(1/3) ≈ 4.5 cm.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-76","question":"Two soap bubbles of radii 3 cm and 4 cm, made from the same solution, are stuck together so that they share a common film. The radius of curvature of the common film is:","options":["12 cm, bulging into the smaller bubble","7 cm, bulging into the larger bubble","12 cm, bulging into the larger bubble","1 cm, bulging into the larger bubble"],"answer":2,"explanation":"The pressure difference across the common film is the difference of the two excess pressures: 4T/r = 4T/3 − 4T/4, so 1/r = 1/3 − 1/4 and r = 12 cm. The smaller bubble has the higher pressure, so the film bulges into the larger one.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-fluids-elasticity-77","question":"A wire of length 2 m is clamped horizontally between two supports so that it is just taut but unstretched. A 2.5 kg mass is hung from its midpoint. If YA = 2 × 10⁵ N for the wire (g = 10 m/s²), the midpoint sags by about:","options":["1.25 cm","10 cm","2.5 cm","5 cm"],"answer":3,"explanation":"Half-length l = 1 m, sag x. Strain ≈ x²/(2l²), so T = YAx²/(2l²); vertical balance 2T(x/l) = mg gives x³ = l³mg/(YA) = 25/(2 × 10⁵) = 1.25 × 10⁻⁴ m³, so x = 0.05 m = 5 cm. The sag goes as the cube root of the load, not linearly.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "phy-fluids-elasticity-78", "question": "A beaker of water placed on a weighing scale reads 2.0 kg. A 1 kg block of density 5000 kg/m³, hung from a spring balance, is lowered until it is fully immersed in the water without touching the beaker (density of water 1000 kg/m³, g = 10 m/s²). The readings of the spring balance and of the weighing scale are:", "options": ["8 N and 22 N", "10 N and 20 N", "8 N and 20 N", "8 N and 30 N"], "answer": 0, "explanation": "Buoyant force = ρ_w V g = 1000 × (1/5000) × 10 = 2 N. The spring balance reads 10 − 2 = 8 N. By Newton's third law the block pushes down on the water with 2 N, so the scale reads 20 + 2 = 22 N. 30 N would mean the whole weight of the block rested on the scale.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-79", "question": "How many of the following statements are correct?\n(A) A body floating in water in a lift that accelerates upward floats with the same fraction of its volume submerged as when the lift is at rest.\n(B) In a freely falling container of water, the buoyant force on an immersed body is zero.\n(C) The pressure at the bottom of a vessel of water in a lift accelerating downward (a < g) is less than when the lift is at rest.\n(D) A cork held at the bottom of a beaker of water and released inside a freely falling lift rises to the surface.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "A: both weight and buoyancy scale with (g + a), so the fraction is unchanged. B: in free fall the effective g is zero, so there is no pressure gradient and no buoyancy. C: P = ρ(g − a)h is smaller. D is wrong: with no buoyancy the cork stays where it is relative to the water.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-fluids-elasticity-80", "question": "Assertion (A): When two soap bubbles of different sizes are connected by a tube, the smaller bubble shrinks and the larger one grows.\nReason (R): The excess pressure inside a soap bubble is inversely proportional to its radius.", "options": ["Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "ΔP = 4T/r, so the smaller bubble has the higher internal pressure, and air flows from it into the larger bubble until the smaller one collapses to a cap with the same radius as the larger. R is exactly the reason for A.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-fluids-elasticity-81","question":"A thin uniform rod of length L and density 9/16 that of water is hinged at its lower end to the bottom of a tank in which the water is 3L/8 deep. The rod rests partly immersed. In equilibrium it makes an angle with the vertical of:","options":["30°","60°","45°","37°"],"answer":1,"explanation":"With immersed length l, moments about the hinge: weight ρ_r L g(L/2) sin θ = buoyancy ρ_w l g(l/2) sin θ, so l = L√(9/16) = 3L/4. The immersed part reaches the surface: l cos θ = 3L/8, so cos θ = 1/2 and θ = 60°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-82","question":"A large open tank has its water surface 2 m above a horizontal pipe that leaves from its base and discharges into the air. Part-way along, the pipe narrows to half the cross-section of its open end (ideal flow, g = 10 m/s², density 1000 kg/m³). The gauge pressure in the narrow section is:","options":["+2 × 10⁴ Pa","−2 × 10⁴ Pa","−6 × 10⁴ Pa","0"],"answer":2,"explanation":"At the open end v = √(2gh) = √40 m/s and the gauge pressure is 0. In the narrow part v is doubled: v² = 160. Bernoulli between the two: P = ½ρ(40 − 160) = −6 × 10⁴ Pa, i.e. below atmospheric. It is not zero just because the pipe is open at the end.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-fluids-elasticity-83", "question": "A block of density 4000 kg/m³ hangs from a steel wire. The extension of the wire is 1.0 mm when the block is in air and 0.8 mm when the block is fully immersed in a liquid. The density of the liquid is:", "options": ["1000 kg/m³", "200 kg/m³", "1250 kg/m³", "800 kg/m³"], "answer": 3, "explanation": "Extension ∝ tension. In the liquid the tension is mg(1 − ρ_l/ρ_b), so 0.8/1.0 = 1 − ρ_l/4000, giving ρ_l = 800 kg/m³. If the liquid were water (1000 kg/m³) the extension would have been 0.75 mm.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-fluids-elasticity-84","question":"Water rises to a height h in a glass capillary tube of internal diameter d. If it is instead allowed to rise between two parallel glass plates held a distance d apart, it rises to a height of:","options":["h/2","h","2h","h/4"],"answer":0,"explanation":"Tube: 2πrT = πr²hρg gives h = 4T/(ρgd). Plates (per unit width): 2T = dh′ρg gives h′ = 2T/(ρgd) = h/2. Each plate has one contact line per unit length, while the tube's perimeter-to-area ratio is twice as large.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-fluids-elasticity-85", "question": "Water rises in a capillary tube and comes to rest at its equilibrium height. Of the work done by the surface-tension forces during the rise, the fraction stored as gravitational potential energy of the raised column is:", "options": ["1", "1/2", "2/3", "1/4"], "answer": 1, "explanation": "Work by surface tension = (2πrT cos θ)h, and with h = 2T cos θ/(rρg) this equals πr²ρgh². The column's potential energy is (πr²hρ)g(h/2) = ½πr²ρgh². The other half is lost as heat through viscosity while the liquid oscillates and settles.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-fluids-elasticity-86","question":"Three open vessels — a narrow-necked flask, a straight cylinder and a wide-mouthed funnel shape — have equal base areas and are filled with water to the same height. The force exerted by the water on the base is:","options":["largest for the wide-mouthed vessel","the same for all three","largest for the narrow-necked flask","proportional to the volume of water in each"],"answer":1,"explanation":"The pressure at the base depends only on the depth: p = p₀ + ρgh. With equal h and equal base area, the force pA is identical, even though the vessels hold different weights of water (the 'hydrostatic paradox'; the walls carry the difference).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-87","question":"Two wires of the same metal have different lengths and different cross-sections. Within the elastic limit, their Young's moduli are:","options":["equal, since Young's modulus depends only on the material","in the ratio of their lengths","in the inverse ratio of their cross-sections","in the ratio of their volumes"],"answer":0,"explanation":"Young's modulus Y = stress/strain is a property of the material (at a given temperature). The extension of a wire depends on L and A, but Y itself does not.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-88","question":"A steel wire (Y = 2 × 10¹¹ N/m²) 2 m long with a cross-section of 1 mm² is stretched by 1 mm. The elastic potential energy stored in it is:","options":["0.5 J","0.1 J","0.025 J","0.05 J"],"answer":3,"explanation":"Required force F = YAΔl/L = 2 × 10¹¹ × 10⁻⁶ × 10⁻³/2 = 100 N. The energy stored is ½FΔl = ½ × 100 × 10⁻³ = 0.05 J (not FΔl, because the force rises from zero).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-89","question":"A light rigid rod 1.2 m long hangs horizontally from two vertical wires of equal length and equal cross-section attached at its ends: one of steel (Y = 2 × 10¹¹ N/m²) and one of brass (Y = 1 × 10¹¹ N/m²). Where must a load be hung for the rod to remain horizontal?","options":["at the middle","0.4 m from the brass wire","0.4 m from the steel wire","0.3 m from the steel wire"],"answer":2,"explanation":"For equal extensions, tension ∝ YA/L, so T_steel = 2T_brass. Moments about the load point: T_s·x = T_b(1.2 − x), i.e. 2x = 1.2 − x, so x = 0.4 m from the steel wire (nearer the stiffer wire, which carries more).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-90","question":"A uniform wooden cylinder floats upright in water with 40 cm of its length submerged. It is pushed down slightly and released. Neglecting viscous effects and the motion of the water, the period of its vertical oscillation is about:","options":["2.51 s","0.63 s","1.26 s","0.4 s"],"answer":2,"explanation":"An extra depth y adds buoyant force ρ_w gAy, so k = ρ_w gA. The mass is ρ_w A h (it floats with depth h), so T = 2π√(m/k) = 2π√(h/g) = 2π × 0.2 ≈ 1.26 s, the same as a pendulum of length h.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-91","question":"A ball of volume 1 litre and density 500 kg/m³ is tied by a thread to the bottom of a tank of water (density 1000 kg/m³) and is fully submerged. The tank is in a lift accelerating upward at 2 m/s² (g = 10 m/s²). The tension in the thread is:","options":["5 N","6 N","4 N","12 N"],"answer":1,"explanation":"In the lift frame effective gravity is g + a = 12 m/s², and buoyancy also scales with it (the pressure gradient is ρ(g + a)). T = (ρ_w − ρ_b)V(g + a) = 500 × 10⁻³ × 12 = 6 N. 5 N ignores the lift's acceleration.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-92","question":"Water flows at 2 m/s through a pipe that then narrows to half the cross-sectional area while rising 1 m. The pressure at the lower, wider section exceeds that at the upper, narrower section by:","options":["1.6 × 10⁴ Pa","6 × 10³ Pa","1 × 10⁴ Pa","4 × 10³ Pa"],"answer":0,"explanation":"Continuity: v₂ = 4 m/s. Bernoulli: p₁ − p₂ = ½ρ(v₂² − v₁²) + ρgh = 500 × 12 + 10⁴ = 6000 + 10000 = 1.6 × 10⁴ Pa. Both the speed increase and the rise lower the pressure.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-93","question":"A small air bubble of radius 1 mm rises steadily through a liquid of density 900 kg/m³ and viscosity 0.5 Pa s (g = 10 m/s²; neglect the mass of the air). Its terminal speed is:","options":["0.4 mm/s","2 mm/s","40 mm/s","4 mm/s"],"answer":3,"explanation":"At terminal speed the upward buoyancy balances the Stokes drag (the bubble's weight is negligible): (4/3)πr³ρg = 6πηrv. So v = 2r²ρg/9η = 2 × 10⁻⁶ × 900 × 10/4.5 = 4 × 10⁻³ m/s = 4 mm/s.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-94","question":"A small solid ball of density 2000 kg/m³ is released from rest inside a viscous liquid of density 1000 kg/m³ (g = 10 m/s²). Its acceleration at the instant of release is:","options":["2.5 m/s²","10 m/s²","zero, since viscosity opposes motion","5 m/s²"],"answer":3,"explanation":"At release the speed is zero, so the viscous drag is zero. Net force = weight − buoyancy = Vg(2000 − 1000), so a = g(1 − 1000/2000) = 5 m/s². The acceleration then decreases towards zero as the drag builds up.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-95","question":"A liquid flows steadily through two horizontal tubes of the same length joined in series; the second tube has half the radius of the first. What fraction of the total pressure drop occurs across the narrower tube?","options":["4/5","1/2","16/17","1/17"],"answer":2,"explanation":"Poiseuille: the same flow Q passes both tubes, and Δp = 8ηLQ/(πr⁴), so Δp ∝ 1/r⁴. The narrow tube has 16 times the resistance, so its share is 16/(16 + 1) = 16/17.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-96","question":"A long glass capillary tube stands vertically with its lower end in water inside a closed box. The box is dropped and falls freely. During the fall, the water in the capillary:","options":["falls back to the outside level","rises and fills the whole length of the tube","stays at its original capillary height","is expelled from the tube"],"answer":1,"explanation":"The capillary height is h = 2T cos θ/(ρg_eff r). In free fall g_eff = 0, so no weight opposes surface tension and the water climbs until it reaches the top of the tube (where the meniscus adjusts its curvature and it stops).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-97","question":"Two clean parallel glass plates are held vertically 0.1 mm apart with their lower edges dipping in water (surface tension 0.07 N/m, contact angle 0°, g = 10 m/s²). The height to which water rises between them is:","options":["14 cm","28 cm","7 cm","1.4 cm"],"answer":0,"explanation":"Per unit length of the plates, surface tension pulls up with 2T (one contact line on each plate). This supports a sheet of water ρghd per unit length, so h = 2T/(ρgd) = 0.14/(1000 × 10 × 10⁻⁴) = 0.14 m. A tube of DIAMETER d would give twice this.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-98","question":"A soap bubble and a water drop have the same excess pressure inside them, and both liquids have the same surface tension. The ratio of the bubble's radius to the drop's radius is:","options":["2","1/2","1","4"],"answer":0,"explanation":"A drop has one surface: Δp = 2T/r. A soap bubble has two surfaces: Δp = 4T/R. Equal excess pressures give 4T/R = 2T/r, so R = 2r.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-99","question":"A square sluice gate 1 m × 1 m is fixed vertically in the wall of a reservoir with its top edge 1 m below the water surface. The depth below the surface of the point through which the resultant water thrust acts (the centre of pressure) is about:","options":["2 m","1.5 m","1.67 m","1.56 m"],"answer":3,"explanation":"Pressure increases with depth, so the thrust acts below the centroid (depth 1.5 m). h_p = h_c + I_c/(A h_c) = 1.5 + (1/12)/(1 × 1.5) ≈ 1.5 + 0.056 = 1.56 m. (The familiar 2/3-depth rule applies only to a gate whose top edge is at the surface.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-100","question":"A Pitot-static tube on an aircraft measures a difference of 6000 Pa between the stagnation pressure and the static pressure. Taking the air density as 1.2 kg/m³ and treating air as incompressible, the aircraft's airspeed is:","options":["141 m/s","70.7 m/s","100 m/s","50 m/s"],"answer":2,"explanation":"At the stagnation point the air is brought to rest, so Δp = ½ρv². v = √(2 × 6000/1.2) = √10⁴ = 100 m/s.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-101","question":"Air (density 1.2 kg/m³) flows past an aircraft wing of area 10 m² at 70 m/s over the upper surface and 60 m/s under the lower surface. Using Bernoulli's principle, the dynamic lift on the wing is:","options":["3900 N","7800 N","600 N","15600 N"],"answer":1,"explanation":"Pressure difference = ½ρ(v_top² − v_bottom²) = 0.6 × (4900 − 3600) = 780 Pa. Lift = 780 × 10 = 7800 N. Note that the difference of squares, not the square of the difference, appears.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-102","question":"A uniform steel bar (length 2 m, cross-section 1 cm², Y = 2 × 10¹¹ N/m²) lies on a smooth floor and is pulled along its length by a force of 10⁴ N applied at one end. Its extension while it accelerates is:","options":["1 mm","0.5 mm","0.25 mm","2 mm"],"answer":1,"explanation":"The tension falls linearly from F at the pulled end to zero at the free end (it only accelerates the part behind it): T(x) = Fx/L. The extension is ∫T dx/(AY) = FL/(2AY) = 10⁴ × 2/(2 × 10⁻⁴ × 2 × 10¹¹) = 5 × 10⁻⁴ m = 0.5 mm, half the value for a uniform tension F.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-103","question":"A wire of a material with Poisson's ratio 0.3 is stretched so that its length increases by 0.1%. The fractional change in its volume is:","options":["an increase of 0.04%","an increase of 0.1%","a decrease of 0.06%","no change"],"answer":0,"explanation":"V ∝ L·d², so ΔV/V = ΔL/L + 2Δd/d = ε − 2σε = (1 − 2σ)ε = 0.4 × 0.1% = 0.04%. Volume would be conserved only if σ were 0.5.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-104","question":"A metal has Young's modulus 2 × 10¹¹ N/m² and Poisson's ratio 0.25. Its bulk modulus is about:","options":["2.67 × 10¹¹ N/m²","0.8 × 10¹¹ N/m²","6 × 10¹¹ N/m²","1.33 × 10¹¹ N/m²"],"answer":3,"explanation":"The elastic constants are related by Y = 3B(1 − 2σ). So B = Y/[3(1 − 0.5)] = 2 × 10¹¹/1.5 ≈ 1.33 × 10¹¹ N/m².","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-105","question":"Steel has a breaking stress of 8 × 10⁸ N/m² and a density of 8000 kg/m³ (g = 10 m/s²). The greatest length of a uniform steel wire that can hang vertically from a support without breaking under its own weight is:","options":["20 km","5 km","10 km","1 km"],"answer":2,"explanation":"The maximum stress, at the top, is the weight of the whole wire divided by its area: ρgL. Breaking occurs when ρgL = 8 × 10⁸, so L = 8 × 10⁸/(8000 × 10) = 10⁴ m = 10 km, independent of the cross-section.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-106","question":"A mercury barometer reads 76 cm on the ground. It is placed in a lift that accelerates upward at 2 m/s² (g = 10 m/s²), the air pressure in the lift being unchanged. The barometer now reads about:","options":["91.2 cm","76 cm","63.3 cm","60.8 cm"],"answer":2,"explanation":"The atmospheric pressure is balanced by ρ(g + a)h in the accelerating frame. With p unchanged, h = 76 × g/(g + a) = 76 × 10/12 ≈ 63.3 cm. A shorter column does not mean the air pressure has fallen.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-107","question":"Two small steel balls of radii r and 2r fall at their terminal speeds through the same viscous oil. The ratio of the rates at which viscous drag converts energy into heat, for the larger ball to the smaller, is:","options":["16","32","8","4"],"answer":1,"explanation":"Terminal speed v ∝ r², and at terminal speed the drag equals the net weight ∝ r³. The power F·v ∝ r³ × r² = r⁵, so doubling r gives 2⁵ = 32.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-108","question":"Water rises to a vertical height of 5 cm in a capillary tube held vertically. If the same tube is tilted to make 60° with the vertical, the length of the water column in the tube becomes:","options":["10 cm","5 cm","2.5 cm","8.7 cm"],"answer":0,"explanation":"The vertical height h = 2T cos θ/ρgr is unchanged by tilting. The column along a tube at 60° to the vertical has length h/cos 60° = 10 cm.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-109","question":"Water rises in a capillary tube to its equilibrium height h. Of the surface energy released by wetting the inner wall, the fraction stored as gravitational potential energy of the raised column is:","options":["two-thirds","all of it","one-quarter","one-half, the rest being dissipated as heat"],"answer":3,"explanation":"Surface tension does work F·h = (2πrT cos θ)h as the liquid rises. The column's PE is mg(h/2) with mg = 2πrT cos θ at equilibrium, i.e. exactly half of that work. The other half is lost as heat in the damped rise and oscillations.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-110","question":"A cork is held at the bottom of a beaker of water by a finger and the beaker is dropped. Just after release, the finger is removed from the cork while beaker and contents are falling freely. Relative to the beaker, the cork:","options":["sinks into the beaker's base","rises to the surface faster than usual","rises at its usual rate","stays at the bottom"],"answer":3,"explanation":"Buoyancy arises from the pressure gradient in the liquid, which is ρg_eff. In free fall g_eff = 0, so the pressure is uniform and there is no buoyant force; the cork and water simply fall together, so the cork stays where it is.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-111","question":"A balloon holds 100 m³ of helium (density 0.18 kg/m³) in air of density 1.2 kg/m³ (g = 10 m/s²). The largest total mass of envelope plus payload that it can just lift is:","options":["18 kg","120 kg","102 kg","138 kg"],"answer":2,"explanation":"Net upthrust on the gas-filled volume = (ρ_air − ρ_He)Vg = 1.02 × 100 × 10 = 1020 N. This can support a mass of 1020/10 = 102 kg for the envelope and payload together.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-112","question":"A large open water tank stands on a trolley on a smooth floor. Water spurts horizontally from a small hole of area 1 cm² located 5 m below the water surface (g = 10 m/s²). The horizontal force on the tank due to the outflow is:","options":["5 N","10 N","20 N","1 N"],"answer":1,"explanation":"Torricelli: v² = 2gh = 100, so v = 10 m/s. The jet carries momentum away at ρav² = 1000 × 10⁻⁴ × 100 = 10 N, which is the reaction on the tank (twice ρgha, the naive 'pressure × area' value).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-113","question":"A thin horizontal tube 0.5 m long, closed at its outer end and open at the other end to the atmosphere, is full of water and rotates at 20 rad/s about a vertical axis through its open end. The pressure at the closed end exceeds atmospheric pressure by:","options":["5 × 10⁴ Pa","2.5 × 10⁴ Pa","1 × 10⁵ Pa","1 × 10⁴ Pa"],"answer":0,"explanation":"The radial pressure gradient supplies the centripetal force: dp/dr = ρω²r, so Δp = ½ρω²L² = ½ × 1000 × 400 × 0.25 = 5 × 10⁴ Pa.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-114","question":"A block of volume 1 litre and density 600 kg/m³ is held completely under water by a light spring attached to the bottom of the tank (spring constant 100 N/m). The extension of the spring is (g = 10 m/s²):","options":["4 cm","6 cm","10 cm","16 cm"],"answer":0,"explanation":"Equilibrium: buoyancy = weight + spring force. kx = (ρ_w − ρ)Vg = 400 × 10⁻³ × 10 = 4 N, so x = 4/100 = 0.04 m = 4 cm (an extension, as the spring pulls the block down).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-115","question":"A thin plate of area 0.1 m² is pulled at a constant 0.1 m/s parallel to itself between two large fixed parallel plates, in a liquid of viscosity 1 Pa s. Its gaps to the two fixed plates are 1 mm and 2 mm. The force needed is:","options":["3.3 N","10 N","5 N","15 N"],"answer":3,"explanation":"Each gap has a linear velocity profile and exerts a drag ηAv/d. Total F = ηAv(1/d₁ + 1/d₂) = 1 × 0.1 × 0.1 × (1000 + 500) = 15 N; the two drags add, they do not combine like resistors in series.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-fluids-elasticity-116","question":"A U-tube contains water. Oil of density 800 kg/m³ is poured into one limb until the oil column is 10 cm long. How far does the top of the oil stand above the water surface in the other limb?","options":["10 cm","8 cm","2 cm","1 cm"],"answer":2,"explanation":"At the level of the oil–water interface the pressures in the two limbs are equal: ρ_oil g(10 cm) = ρ_w g h_w, so h_w = 8 cm. The oil top is therefore 10 − 8 = 2 cm above the water surface in the other limb.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-fluids-elasticity-117","question":"A wooden block floats in a beaker of water with 60% of its volume submerged. The beaker is placed in a lift that accelerates upward at g/2. The fraction of the block's volume submerged now is:","options":["90%","60%","40%","30%"],"answer":1,"explanation":"Floating requires ρ_block V g_eff = ρ_w V_sub g_eff. Both the weight and the buoyancy scale with the same effective g, so V_sub/V = ρ_block/ρ_w = 0.6 is unchanged.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-fluids-elasticity-118","question":"An open tank stands on level ground with its water surface 4 m above the ground. Two small holes are made in its side at depths of 1 m and 3 m below the water surface. The horizontal jets strike the ground:","options":["at 2√3 m and 2 m from the tank respectively","at the same point, 2√3 m from the tank","at 4 m and 2√3 m from the tank respectively","at the same point, 4 m from the tank"],"answer":1,"explanation":"A hole at depth h, height (H − h) above the ground, gives a range 2√(h(H − h)). For h = 1 m: 2√3; for h = 3 m: 2√3. Holes symmetric about mid-height give equal ranges, here 2√3 ≈ 3.46 m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
